  <fieldset className="task-date-choice"><legend>موعد المهمة</legend><div><button type="button" className={!scheduled?"selected":""} aria-pressed={!scheduled} onClick={()=>{setScheduled(false);setDate("");setTime("");setAlert(0)}}>غير مجدولة</button><button type="button" className={scheduled?"selected":""} aria-pressed={scheduled} onClick={()=>{setScheduled(true);setDate(value=>value||today())}}>تحديد موعد</button></div></fieldset>
  {scheduled&&<><CalendarDateField label="اختر تاريخ المهمة" date={date||today()} calendar="gregory" onChange={setDate}/><label>وقت الموعد <small>اختياري</small><input type="time" value={time} onChange={e=>setTime(e.target.value)}/></label><ReminderSelect value={alert} onChange={setAlert}/></>}
