  <button className="primary" disabled={!title.trim()||scheduled&&!date} onClick={()=>{const reminder=scheduled?(alert>0?{mode:"before" as const,value:alert}:time?{mode:"time" as const,value:time}:{mode:"none" as const}):{mode:"none" as const};onSave({...editing,id:editing?.id??`task-${Date.now()}`,title:title.trim(),date:scheduled?date:undefined,time:scheduled?time||undefined:undefined,urgent:scheduled?false:urgent,completedAt:editing?.completedAt,archivedAt:editing?.archivedAt,reminder});close()}}>{editing?"حفظ":"أضف المهمة"}</button>
  {editing&&!editing.archivedAt&&<div className="task-management"><button className="archive-task" onClick={()=>setConfirmAction("archive")}>أرشفة المهمة</button><button className="delete-activity" onClick={()=>setConfirmAction("delete")}>حذف المهمة</button></div>}
